const parsed = $('OpenAI2').item.json.message.content;
const newAmount = parsed.amount;
const newToWhom = parsed.to_whom?.toLowerCase().trim();
const newDirection = parsed.direction;
const chatId = $('Telegram Trigger1').item.json.message.chat.id;

const match = items.find(item => {
  const debt = item.json;
  return debt.to_whom?.toLowerCase().trim() === newToWhom &&
         debt.direction === newDirection;
});

if (match) {
  const existingAmount = match.json.amount;
  const existingId = match.json.id;

  return [{
    json: {
      match: true,
      existing_debt_id: existingId,
      existing_amount: existingAmount,
      new_amount: existingAmount + newAmount
    }
  }];
} else {
  return [{
    json: {
      match: false,
      to_whom: parsed.to_whom,
      amount: parsed.amount,
      direction: parsed.direction,
      date: parsed.date,
      chat_id: chatId
    }
  }];
}

const today = new Date();
const currentDay = today.getDate();
const currentMonth = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;

return items
  .filter(item => Number(item.json.day_of_month) === currentDay)
  .map(item => {
    return {
      json: {
        ...item.json,
        current_month: currentMonth
      }
    };
  });

