const output = {
  user_id: $("Telegram Trigger1").item.json.message.chat.id,
  source: input.source || previous.source,
  amount: input.amount ?? previous.amount,
  comment: input.comment ?? previous.comment ?? null,
  active: true,
  updated_at: new Date().toISOString()
};

if (resolvedDay !== undefined && resolvedDay !== null) {
  output.day_of_month = Number(resolvedDay);
}

return [{ json: output }];

const now = new Date();
now.setMonth(now.getMonth() - 1);

const lastMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

return [{
  json: {
    last_month: lastMonth
  }
}];

